function e(t){return t==null?"R$ 0,00":new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(t)}function r(t){if(!t)return null;if(t instanceof Date)return isNaN(t.getTime())?null:t;if(typeof t=="string"){const n=new Date(t);return isNaN(n.getTime())?null:n}if(typeof t=="number"){const n=new Date(t);return isNaN(n.getTime())?null:n}return null}function i(t){const n=r(t);return n?new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"2-digit",year:"numeric"}).format(n):"-"}function u(t){const n=r(t);return n?new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(n):"-"}function o(t){return t?t.split(" ").map(n=>n[0]).join("").substring(0,2).toUpperCase():"?"}export{i as a,u as b,e as f,o as g};
